// Response is { files: [...] } from the Drive API
const raw = $input.first().json;
const files = raw.files || [];
if (files.length === 0) {
  // Return the raw response so you can see what came back
  throw new Error('No files found. Raw API response: ' + JSON.stringify(raw));
}
// Already ordered by modifiedTime desc from the API, so just take first
return [{ json: files[0] }];

const rawText = $input.first().json.data || '';
const info = $('Sort and Pick Most Recent').first().json;

// ── ESCAPE HTML ──────────────────────────────────────────────────────────────
function esc(s) {
  return String(s)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');
}

// ── PARSE DOCUMENT INTO SECTIONS ────────────────────────────────────────────
function parseDoc(raw) {
  const blocks = raw.replace(/\r/g, '').split(/\n{2,}/);
  const out = [];
  let title = null;

  for (const block of blocks) {
    const lines = block.split('\n').map(l => l.trim()).filter(Boolean);
    if (!lines.length) continue;
    const hasBullet = lines.some(l => /^[\u2022*\-]/.test(l));

    if (lines.length === 1 && !hasBullet && lines[0].length < 120) {
      // Single short non-bullet line = section title
      if (title !== null) out.push({ title: title, items: [] });
      title = lines[0];
    } else {
      const items = lines.map(l => ({
        text: l.replace(/^[\u2022*\-]\s*/, '').trim(),
        sub: /^\s{3,}/.test(l),
        action: /action item|assigned to|pending:|urgent|blocked|due:|follow.up|must:|todo:/i.test(l)
      })).filter(i => i.text);

      if (title !== null) {
        out.push({ title: title, items: items });
        title = null;
      } else if (items.length > 0) {
        // Orphan block — use first item as title
        const autoTitle = items[0].text.split(':')[0].trim().slice(0, 70);
        out.push({ title: autoTitle, items: items.slice(1) });
      }
    }
  }

  if (title) out.push({ title: title, items: [] });
  return out.filter(s => s.title && s.title.length > 1);
}

// ── CATEGORISE ───────────────────────────────────────────────────────────────
function cat(title) {
  const t = title.toLowerCase();
  if (/jaguar|lewis|fordham|canvas forum|nett.?sol|jon hart|titan|spears|guac|certitrek|cfg|albert|ground up/.test(t)) return 'client';
  if (/daria|hesham|jasmin|david smith|devoreaux|agustin|chareze|lorenna|princess|gwen|muhammad yousaf/.test(t)) return 'team';
  if (/crm copilot|ai website|custom gpt|website change/.test(t)) return 'product';
  return 'ops';
}

// ── BUILD DATA ───────────────────────────────────────────────────────────────
const sections = parseDoc(rawText);
const d = new Date(info.modifiedTime || info.createdTime || Date.now());
const dateStr = d.toLocaleDateString('en-US', { weekday: 'short', month: 'short', day: 'numeric', year: 'numeric' });
const timeStr = d.toLocaleTimeString('en-US', { hour: '2-digit', minute: '2-digit', timeZoneName: 'short' });
const total   = sections.length;
const actions = sections.reduce((n, s) => n + s.items.filter(i => i.action).length, 0);
const clients = sections.filter(s => cat(s.title) === 'client').length;
const team    = sections.filter(s => cat(s.title) === 'team').length;
const docLink = esc(info.webViewLink || '#');

const CM = {
  client:  { label: 'Client',     color: '#3b82f6', dim: 'rgba(59,130,246,0.18)',  icon: '&#x1F3E2;' },
  team:    { label: 'Team',       color: '#a855f7', dim: 'rgba(168,85,247,0.18)',  icon: '&#x1F465;' },
  product: { label: 'Product',    color: '#22c55e', dim: 'rgba(34,197,94,0.18)',   icon: '&#x1F916;' },
  ops:     { label: 'Operations', color: '#f97316', dim: 'rgba(249,115,22,0.18)',  icon: '&#x2699;&#xFE0F;' }
};

// ── RENDER CARD ──────────────────────────────────────────────────────────────
function renderCard(s) {
  const c = cat(s.title);
  const m = CM[c];
  const ac = s.items.filter(i => i.action).length;

  const listItems = s.items.map(item => {
    const cls = ['bi'];
    if (item.sub)    cls.push('bs');
    if (item.action) cls.push('ba');
    // Bold label: lines starting with "Word: " pattern
    let txt = esc(item.text);
    if (/^[A-Z][A-Za-z &()]{2,50}:\s/.test(item.text)) {
      txt = txt.replace(/^([^:]{1,55}:\s)/, '<strong>$1</strong>');
    }
    return '<li class="' + cls.join(' ') + '">' + txt + '</li>';
  }).join('');

  return '<div class="card c-' + c + '" data-c="' + c + '">'
    + '<div class="ch" style="border-top:3px solid ' + m.color + '">'
      + '<div class="cr">'
        + '<h3>' + esc(s.title) + '</h3>'
        + '<span class="badge" style="background:' + m.dim + ';color:' + m.color + '">' + m.icon + ' ' + m.label + '</span>'
      + '</div>'
      + (ac > 0
        ? '<div class="arow"><span class="adot"></span>' + ac + ' action item' + (ac !== 1 ? 's' : '') + '</div>'
        : '')
    + '</div>'
    + '<div class="cb">'
      + (listItems
        ? '<ul class="blist">' + listItems + '</ul>'
        : '<p class="nc">No details recorded.</p>')
    + '</div>'
  + '</div>';
}

const cardsHtml = sections.map(renderCard).join('\n');

// ── HTML PAGE ─────────────────────────────────────────────────────────────────
const html = `<!DOCTYPE html>
<html lang='en'>
<head>
<meta charset='UTF-8'>
