*{box-sizing:border-box;margin:0;padding:0}
html{scroll-behavior:smooth}
body{font-family:'Inter',system-ui,sans-serif;background:var(--bg);color:var(--tx);min-height:100vh;font-size:14px;line-height:1.6}

/* ── HEADER ─────────────────────────────────────────────────────────── */
.hdr{position:sticky;top:0;z-index:99;background:rgba(7,11,24,.93);backdrop-filter:blur(18px);-webkit-backdrop-filter:blur(18px);border-bottom:1px solid var(--b0);padding:14px 24px}
.hdr-top{display:flex;align-items:center;justify-content:space-between;gap:16px;flex-wrap:wrap}
.logo{display:flex;align-items:center;gap:12px}
.logo-ico{width:40px;height:40px;background:linear-gradient(135deg,#3b82f6,#8b5cf6);border-radius:10px;display:flex;align-items:center;justify-content:center;font-size:22px;flex-shrink:0;box-shadow:0 4px 15px rgba(59,130,246,.3)}
.logo h1{font-size:17px;font-weight:700;letter-spacing:-.02em}
.logo p{font-size:11px;color:var(--mt);margin-top:1px}
.hdr-right{display:flex;align-items:center;gap:10px;flex-wrap:wrap}
.upd{font-size:11px;color:var(--mt);padding:5px 13px;background:var(--s0);border:1px solid var(--b0);border-radius:20px;white-space:nowrap}
.sbx{position:relative}
.sbx input{width:270px;padding:8px 12px 8px 34px;background:var(--s0);border:1px solid var(--b0);border-radius:8px;color:var(--tx);font-size:13px;font-family:inherit;outline:none;transition:border-color .2s,box-shadow .2s}
.sbx input:focus{border-color:var(--blue);box-shadow:0 0 0 3px rgba(59,130,246,.15)}
.sbx input::placeholder{color:var(--mt)}
.sbx svg{position:absolute;left:10px;top:50%;transform:translateY(-50%);width:14px;height:14px;color:var(--mt);stroke:currentColor;fill:none;stroke-width:2;stroke-linecap:round;stroke-linejoin:round;pointer-events:none}
.btn{padding:7px 15px;border-radius:8px;border:none;cursor:pointer;font-size:13px;font-weight:500;font-family:inherit;transition:all .2s;white-space:nowrap}
.btn-g{background:var(--s0);color:var(--tx);border:1px solid var(--b0)}
