.main{padding:0 24px 48px}
.grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(360px,1fr));gap:14px;align-items:start}
.card{background:var(--s0);border:1px solid var(--b0);border-radius:14px;overflow:hidden;transition:transform .2s,box-shadow .2s,background .2s;display:flex;flex-direction:column}
.card:hover{transform:translateY(-2px);box-shadow:0 12px 32px rgba(0,0,0,.4);background:var(--s1)}
.card.hidden{display:none}

