.ch{padding:14px 18px 12px;border-bottom:1px solid var(--b0)}
.cr{display:flex;align-items:flex-start;justify-content:space-between;gap:10px}
.ch h3{font-size:14px;font-weight:600;line-height:1.35;color:var(--tx)}
.badge{font-size:10px;font-weight:600;padding:3px 10px;border-radius:10px;white-space:nowrap;flex-shrink:0;letter-spacing:.04em}
.arow{display:flex;align-items:center;gap:6px;font-size:11px;color:var(--amb);margin-top:7px}
