::-webkit-scrollbar{width:5px;height:5px}
::-webkit-scrollbar-track{background:transparent}
::-webkit-scrollbar-thumb{background:rgba(255,255,255,.15);border-radius:3px}
::-webkit-scrollbar-thumb:hover{background:rgba(255,255,255,.25)}
</style>
</head>
<body>

<header class='hdr'>
  <div class='hdr-top'>
    <div class='logo'>
      <div class='logo-ico'>&#x1F4CA;</div>
      <div>
        <h1>Weekly Operations Dashboard</h1>
        <p>Service Push &middot; AI-Powered Ops Intelligence</p>
      </div>
    </div>
    <div class='hdr-right'>
      <div class='sbx'>
        <svg viewBox='0 0 24 24'><circle cx='11' cy='11' r='8'/><line x1='21' y1='21' x2='16.65' y2='16.65'/></svg>
        <input type='text' id='srch' placeholder='Search sections, people, topics&hellip;'>
      </div>
      <span class='upd'>&#x1F550; ${dateStr} &middot; ${timeStr}</span>
      <button class='btn btn-g' onclick='window.print()'>&#x1F5A8; Print</button>
      <button class='btn btn-b' onclick='location.reload()'>&#x21BB; Refresh</button>
    </div>
  </div>
</header>

<div class='stats'>
  <div class='sc'><div class='si si-bl'>&#x1F4CB;</div><div class='sv'><label>Total Sections</label><strong>${total}</strong></div></div>
  <div class='sc'><div class='si si-am'>&#x26A1;</div><div class='sv'><label>Action Items</label><strong>${actions}</strong></div></div>
  <div class='sc'><div class='si si-bl'>&#x1F3E2;</div><div class='sv'><label>Client Topics</label><strong>${clients}</strong></div></div>
  <div class='sc'><div class='si si-pu'>&#x1F465;</div><div class='sv'><label>Team Updates</label><strong>${team}</strong></div></div>
</div>

<div class='filters'>
  <button class='fp act' data-f='all'>All Sections</button>
  <button class='fp' data-f='client'>&#x1F3E2; Clients</button>
  <button class='fp' data-f='team'>&#x1F465; Team</button>
  <button class='fp' data-f='product'>&#x1F916; Product &amp; AI</button>
  <button class='fp' data-f='ops'>&#x2699;&#xFE0F; Operations</button>
</div>

<main class='main'>
  <div class='grid' id='grid'>
    ${cardsHtml}
  </div>
  <div class='nores' id='nores'>
    <div class='nores-ico'>&#x1F50D;</div>
    <p>No sections match your search</p>
  </div>
</main>

<footer class='footer'>
  <span>&#x1F4C4; Source: <a href='${docLink}' target='_blank' rel='noopener'>7 Day Recap &mdash; Google Docs</a></span>
  <span class='footer-sep'>|</span>
  <span>Powered by n8n &amp; Google Drive</span>
  <span class='footer-sep'>|</span>
  <span>${dateStr}</span>
</footer>

<script>
(function(){
  const cards = Array.from(document.querySelectorAll('.card'));
  const nores = document.getElementById('nores');
  const grid  = document.getElementById('grid');
  let curF = 'all', curQ = '';

  function apply() {
    let vis = 0;
    cards.forEach(c => {
      const catOk = curF === 'all' || c.dataset.c === curF;
      const qOk   = !curQ || c.textContent.toLowerCase().includes(curQ);
      const show  = catOk && qOk;
      c.classList.toggle('hidden', !show);
      if (show) vis++;
    });
    nores.style.display = vis === 0 ? 'block' : 'none';
  }

  document.getElementById('srch').addEventListener('input', e => {
    curQ = e.target.value.toLowerCase().trim();
    apply();
  });

  document.querySelectorAll('.fp').forEach(p => {
    p.addEventListener('click', () => {
      document.querySelectorAll('.fp').forEach(x => x.classList.remove('act'));
      p.classList.add('act');
      curF = p.dataset.f;
      apply();
    });
  });
})();
</script>

</body>
</html>`;

